bootforge/functions-deep/higher-order/fu.solution:
export function calculate(op, a, b) {
  const table = {
    add: (x, y) => x + y,
    sub: (x, y) => x - y,
    mul: (x, y) => x * y,
  };
  const fn = table[op];
  if (!fn) return null;
  return fn(a, b);
}

