export function maxBy(items, fn) {
  if (items.length === 0) return null;
  let best = items[0];
  let bestScore = fn(best);
  for (const item of items.slice(1)) {
    const score = fn(item);
    if (score > bestScore) {
      best = item;
      bestScore = score;
    }
  }
  return best;
}

