bootforge/functions-deep/applied-pattern.solution:
export function makeCounterObj() {
  return {
    count: 0,
    inc() {
      this.count += 1;
      return this.count;
    },
    reset() {
      this.count = 0;
      return this.count;
    },
  };
}

