bootforge/functions-deep/applied-pattern.solution:
export function makeAccount(balance) {
  return {
    balance,
    deposit(n) {
      this.balance += n;
      return this.balance;
    },
    withdraw(n) {
      if (n > this.balance) return 'insufficient';
      this.balance -= n;
      return this.balance;
    },
  };
}

