bootforge/functions-deep/applied-pattern.solution:
export function makeTodoList() {
  return {
    todos: [],
    add(text) {
      this.todos.push({ text, done: false });
      return this;
    },
    complete(text) {
      const todo = this.todos.find((t) => t.text === text);
      if (todo) todo.done = true;
      return this;
    },
    pending() {
      return this.todos.filter((t) => !t.done).map((t) => t.text);
    },
  };
}

