bootforge/functions-deep/applied-pattern.solution:
export function makeCalc(start) {
  return {
    value: start,
    add(n) {
      this.value += n;
      return this;
    },
    sub(n) {
      this.value -= n;
      return this;
    },
    mul(n) {
      this.value *= n;
      return this;
    },
    result() {
      return this.value;
    },
  };
}
